  cyl(x, y, z, r, h, col, mat = 0) { this.add('cyl', x, y, z, r * 2, h, r * 2, 0, col, mat); }
  ball(x, y, z, r, col, sy = 1, mat = MAT.LEAF) { this.add('ball', x, y, z, r * 2, r * 2 * sy, r * 2, 0, col, mat); }
