  if (!p.noShadow) {
    const rad = p.down ? 1.0 : 0.52;
    buf.push(x, y + 0.022, z, rad * 2.1, 0.012, rad * 2.1, yaw, [0.05, 0.06, 0.08], MAT.FLAT);
