    if (!this.hint) return;
    const a = clamp(this.hintTimer / 0.5, 0, 1);
    ctx.save();
    ctx.textAlign = 'center';
    ctx.font = `500 ${15 * s}px ${FONT}`;
    const cx = this.w / 2, cy = this.h * 0.68;
    const wpx = ctx.measureText(this.hint).width;
    ctx.fillStyle = `rgba(8,11,16,${0.62 * a})`;
