  showHint(text, time = 2.4) { this.hint = text; this.hintTimer = time; }

  drawClock(ctx, game, s) {
    const w = this.w;
    ctx.save();
    ctx.textAlign = 'center';
    ctx.font = `500 ${11 * s}px ${FONT}`;
    ctx.fillStyle = 'rgba(255,255,255,0.42)';
